def prog_name():
    return sys.argv[0]

def eprint(s):
    sys.stderr.write(s)

def format_human(size):
    # ls human: <1024 -> integer, else X.XK etc without B
    if size < 1024:
        return str(size)
    units = ['K','M','G','T','P','E']
    f = float(size)
    # find unit
    for i, u in enumerate(units):
        # divisor = 1024^(i+1)
        div = 1024 ** (i+1)
        nxt = 1024 ** (i+2) if i+1 < len(units) else None
        if nxt is None or size < nxt:
            # check if size >= div (should be, since we already know size>=1024 and we iterate)
            # Actually need to find largest div <= size
            # So break when size < next divisor
            if size >= div:
                v = f / div
                return f"{v:.1f}{u}"
            else:
                continue
    # fallback
    v = f / (1024 ** len(units))
    return f"{v:.1f}{units[-1]}"

def format_human_index(size, use_bytes):
    # index verbose: bytes with B, human with B
    if use_bytes:
        return f"{size}B"
    if size < 1024:
        return f"{size}B"
    units = ['K','M','G','T','P','E']
    f = float(size)
    for i, u in enumerate(units):
        div = 1024 ** (i+1)
        nxt = 1024 ** (i+2) if i+1 < len(units) else None
        if nxt is None or size < nxt:
            if size >= div:
                v = f / div
                return f"{v:.1f}{u}B"
    v = f / (1024 ** len(units))
    return f"{v:.1f}{units[-1]}B"

def format_size_ls(size, use_bytes, use_count=False, is_count=False):
    # for ls: human width 6, bytes width 12? Actually for count without bytes, width 6, with bytes width 12?
    # is_count indicates value is count, not size
    if is_count:
        if use_bytes:
            return f"{size:12d}"
        else:
            return f"{size:6d}"
    else:
        if use_bytes:
            return f"{size:12d}"
        else:
            h = format_human(size)
            return f"{h:>6}"

def format_size_topn(size, use_bytes):
    # topn width 12 always, human with same human? but human for topn uses same as ls human? e.g., 16.0K vs 16384?
    # For topn human, format same as ls human but padded to 12?
    if use_bytes:
        return f"{size:12d}"
    else:
        h = format_human(size)
        return f"{h:>12}"

def format_size_info(size, use_bytes, apparent_flag):
    # info Size column: human or bytes? human width? Actually info prints table with header, sizes?
    # Info line: "Date       Time       Files    Dirs    Size Path"
    # For human, size is human (e.g., 112.0K) with width? Let's see: header "    Size" (4 spaces + Size =? ) Need to replicate info formatting exactly.
    # We'll handle info formatting separately.
    pass

PYEOF
wc -l ./duc.py
