{"command": "cat >> ./duc.py <<'PYEOF'

def build_short_map(cmd):
    spec = CMD_SPECS.get(cmd, {})
    # merge with global
    merged = {}
    for k,v in GLOBAL_SPEC.items():
        merged[k]=v
    for k,v in spec.items():
        merged[k]=v
    # build short->(long, takes_arg) and long->(short, takes_arg)
    short_to_long = {}
    long_to = {}
    for longname,(short,takes) in merged.items():
        long_to[longname]=(short,takes)
        if short:
            # if duplicate short? e.g., different longs share same short? Should not happen per cmd, but global + cmd may conflict?
            # e.g., index has -H for check-hard-links, info has -H for histogram, both distinct per cmd, no conflict with global (global has h,q,v but lowercase? H vs h distinct)
            short_to_long[short]=(longname,takes)
    return long_to, short_to_long

def parse_cmd_options(cmd, args):
    # returns (opts dict long->value, positionals list, error string or None, help_flag, version_flag)
    # opts values: for flags, True; for args, string value
    # On error, returns (None, None, error_msg)
    long_to, short_to_long = build_short_map(cmd)
    opts = {}
    pos = []
    i=0
    end_opts=False
    prog = prog_name()
    while i < len(args):
        a = args[i]
        if end_opts:
            pos.append(a)
            i+=1
            continue
        if a == '--':
            end_opts=True
            i+=1
            continue
        if a == '-':
            pos.append(a)
            i+=1
            continue
        if a.startswith('--'):
            # long
            if '=' in a:
                name, val = a[2:].split('=',1)
                # check if name valid
                if name not in long_to:
                    return None, None, f"{prog}: unrecognized option '--{name}'\nTry 'duc --help' for more information.\n"
                short, takes = long_to[name]
                if not takes:
                    return None, None, f"{prog}: option '--{name}' doesn't allow an argument\nTry 'duc --help' for more information.\n"
                opts[name]=val
                i+=1
                continue
            else:
                name = a[2:]
                if name not in long_to:
                    return None, None, f"{prog}: unrecognized option '--{name}'\nTry 'duc --help' for more information.\n"
                short, takes = long_to[name]
                if takes:
                    # need next arg
                    if i+1 >= len(args):
                        return None, None, f"{prog}: option '--{name}' requires an argument\nTry 'duc --help' for more information.\n"
                    opts[name]=args[i+1]
                    i+=2
                    continue
                else:
                    opts[name]=True
                    i+=1
                    continue
        elif a.startswith('-') and len(a)>1:
            # short cluster
            j=1
            consumed_next=False
            while j < len(a):
                ch = a[j]
                if ch not in short_to_long:
                    return None, None, f"{prog}: invalid option -- '{ch}'\nTry 'duc --help' for more information.\n"
                longname, takes = short_to_long[ch]
                if takes:
                    # rest of this arg as value if any, else next arg
                    if j+1 < len(a):
                        opts[longname]=a[j+1:]
                    else:
                        if i+1 >= len(args):
                            return None, None, f"{prog}: option requires an argument -- '{ch}'\nTry 'duc --help' for more information.\n"
                        opts[longname]=args[i+1]
                        consumed_next=True
                    break
                else:
                    opts[longname]=True
                    j+=1
                    continue
            if consumed_next:
                i+=2
            else:
                # if we broke due to takes with attached value, advance i by 1
                # else we consumed all chars
                i+=1
            continue
        else:
            pos.append(a)
            i+=1
    return opts, pos, None

PYEOF
wc -l ./duc.py
"}

