{"command": "cat >> ./duc.py <<'PYEOF'

def get_default_db():
    xdg = os.environ.get('XDG_CACHE_HOME')
    home = os.environ.get('HOME', os.path.expanduser('~'))
    if xdg:
        return os.path.join(xdg, 'duc', 'duc.db')
    else:
        return os.path.join(home, '.cache', 'duc', 'duc.db')

def read_config_files():
    # returns list of (filepath, sections dict) in order
    files = []
    home = os.environ.get('HOME', os.path.expanduser('~'))
    # /etc/ducrc
