import subprocess, os, tempfile, shutil

def run_orig(args, cwd="/workspace", env=None):
    import os as _os
    e=_os.environ.copy()
    if env: e.update(env)
    p=subprocess.run(["/workspace/executable"]+args, capture_output=True, text=True, env=e, cwd=cwd)
    # normalize prog name
    def norm(s):
        return s.replace("/workspace/executable","PROG").replace("./duc.py","PROG").replace("/workspace/duc.py","PROG")
    return p.stdout, norm(p.stderr), p.returncode

def run_mine(args, cwd="/workspace", env=None):
    import os as _os
    e=_os.environ.copy()
    if env: e.update(env)
    # replace db paths with mine equivalents? For broad tests that use fixed dbs, need to map orig db to mine db
    # For simplicity, caller should pass already-mapped args (with correct db paths)
    p=subprocess.run(["/workspace/duc.py"]+args, capture_output=True, text=True, env=e, cwd=cwd)
    def norm(s):
        return s.replace("/workspace/duc.py","PROG").replace("/workspace/executable","PROG").replace("./duc.py","PROG")
    return p.stdout, norm(p.stderr), p.returncode

# Test help/version/unknown
tests = [
 (["--version"], {}, "/workspace"),
 (["--help"], {}, "/workspace"),
 (["help"], {}, "/workspace"),
 (["help","ls"], {}, "/workspace"),
 (["help","--all"], {}, "/workspace"),
 (["ls","--help"], {}, "/workspace"),
 (["index","--help"], {}, "/workspace"),
 (["ls","--unknown"], {}, "/workspace"),
 (["ls","-d","/nonexistent.db"], {}, "/workspace"),
 (["info","-d","/nonexistent.db"], {}, "/workspace"),
]

for args, env, cwd in tests:
    o1,e1,c1=run_orig(args, cwd, env)
    o2,e2,c2=run_mine(args, cwd, env)
    # for help/version, prog name not in output (except errors which have PROG normalized)
    if o1==o2 and e1==e2 and c1==c2:
        print(f"OK {args}")
    else:
        print(f"DIFF {args} rc {c1} vs {c2}")
        if o1!=o2:
            print(f"  out {repr(o1[:200])} vs {repr(o2[:200])}")
        if e1!=e2:
            print(f"  err {repr(e1[:200])} vs {repr(e2[:200])}")
